#include <bits/stdc++.h>
using namespace std;
// target[i] = h + min(i, n-1-i); keep elements whose a[i]-min(i,n-1-i) equals the most common value
int main(){
    int n; cin >> n; vector<long long> a(n);
    for (auto &x : a) cin >> x;
    unordered_map<long long,int> cnt; int best = 0;
    for (int i = 0; i < n; i++) {
        long long key = a[i] - min(i, n-1-i);
        // if the problem demands positive heights, skip keys < 1 here
        best = max(best, ++cnt[key]);
    }
    cout << n - best << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// query (l,r,a,d): add a + (i-l)*d to every i in [l,r]  ==  d*i + (a - l*d)
int main(){
    int n, q; cin >> n >> q; vector<long long> arr(n+1);
    for (int i = 1; i <= n; i++) cin >> arr[i];
    vector<long long> c1(n+2,0), c0(n+2,0);   // coefficient of i, constant term
    while (q--) {
        long long l, r, a, d; cin >> l >> r >> a >> d;
        c1[l] += d;          c1[r+1] -= d;
        c0[l] += a - l*d;    c0[r+1] -= a - l*d;
    }
    long long s1 = 0, s0 = 0;
    for (int i = 1; i <= n; i++) {
        s1 += c1[i]; s0 += c0[i];
        cout << arr[i] + s1*i + s0 << " \n"[i==n];
    }
}

#include <bits/stdc++.h>
using namespace std;
// shortest circular window containing all of 0..M-1 (M = mex of whole array)
int main(){
    int n; cin >> n; vector<int> a(n);
    for (auto &x : a) cin >> x;
    vector<bool> seen(n+2,false);
    for (int x : a) if (x <= n) seen[x] = true;
    int M = 0; while (seen[M]) M++;
    if (M == 0) { cout << 0 << "\n"; return 0; }
    vector<int> cnt(M,0); int have = 0, best = n, l = 0;
    for (int r = 0; r < 2*n; r++) {           // doubled array = all rotations
        int x = a[r % n];
        if (x < M && cnt[x]++ == 0) have++;
        while (r - l + 1 > n) { int y = a[l % n]; if (y < M && --cnt[y] == 0) have--; l++; }
        while (have == M) {
            best = min(best, r - l + 1);
            int y = a[l % n]; if (y < M && --cnt[y] == 0) have--; l++;
        }
    }
    cout << best << "\n";
}

