#include <bits/stdc++.h>
using namespace std;
// CF 1416C XOR Inverse: decide bits greedily from MSB, counting inversions inside groups
long long c[31][2];
void go(const vector<int>& v, int b) {
    if (b < 0 || v.size() < 2) return;
    vector<int> L, R; long long ones = 0, zeros = 0;
    for (int x : v) {
        if (x >> b & 1) { c[b][1] += zeros; ones++; R.push_back(x); } // 0 before 1: inversion if bit flipped
        else            { c[b][0] += ones;  zeros++; L.push_back(x); } // 1 before 0: inversion now
    }
    go(L, b-1); go(R, b-1);
}
int main(){
    int n; cin >> n; vector<int> a(n); for (auto &x : a) cin >> x;
    go(a, 30);
    long long inv = 0; int X = 0;
    for (int b = 30; b >= 0; b--) {
        if (c[b][1] < c[b][0]) { inv += c[b][1]; X |= 1 << b; }
        else inv += c[b][0];
    }
    cout << inv % 1000000007 << " " << X << "\n";
}

