#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1e9+7;
// answer = (K-1)^N - #arrays where every adjacent pair has gcd>1 ; Mobius to count coprime neighbours
int main(){
    long long N, K; cin >> N >> K;
    vector<int> mu(K+1, 1), isP(K+1, 1);
    for (int i = 2; i <= K; i++) if (isP[i]) for (int j = i; j <= K; j += i) {
        if (j > i) isP[j] = 0; mu[j] = -mu[j];
        if ((long long)j % ((long long)i*i) == 0) mu[j] = 0;
    }
    vector<long long> f(K+1, 0); for (int v = 2; v <= K; v++) f[v] = 1;
    for (int step = 2; step <= N; step++) {
        vector<long long> S(K+1, 0); long long tot = 0;            // S[d] = sum f over multiples of d
        for (int d = 1; d <= K; d++) for (int m = d; m <= K; m += d) S[d] = (S[d] + f[m]) % MOD;
        for (int v = 2; v <= K; v++) tot = (tot + f[v]) % MOD;
        vector<long long> g(K+1, 0), cop(K+1, 0);
        for (int d = 1; d <= K; d++) if (mu[d]) for (int v = d; v <= K; v += d)
            cop[v] = (cop[v] + mu[d] * S[d]) % MOD;                 // sum f[u] with gcd(u,v)=1
        for (int v = 2; v <= K; v++) g[v] = ((tot - cop[v]) % MOD + MOD) % MOD;
        f = g;
    }
    long long bad = 0, all = 1;
    for (int v = 2; v <= K; v++) bad = (bad + f[v]) % MOD;
    for (int i = 0; i < N; i++) all = all * (K-1) % MOD;
    cout << ((all - bad) % MOD + MOD) % MOD << "\n";
}

