// ways[i] = ways[i-1] + ways[i-2]; ways[0]=ways[1]=1
long long climbStairs(int n){
    long long a = 1, b = 1;            // ways(0), ways(1)
    for (int i = 2; i <= n; i++) { long long c = a + b; a = b; b = c; }
    return b;
}
