// F(0)=0, F(1)=1, F(n)=F(n-1)+F(n-2), computed with two variables
long long fib(int n){
    long long a = 0, b = 1;
    for (int i = 0; i < n; i++) { long long c = a + b; a = b; b = c; }
    return a;   // F(n)
}
