#include <bits/stdc++.h>
using namespace std;
vector<long long> memo;
long long fibMemo(int n){                    // top-down
    if (n <= 1) return n;
    if (memo[n] != -1) return memo[n];
    return memo[n] = fibMemo(n-1) + fibMemo(n-2);
}
int main(){
    int n; cin >> n;                          // print first n terms
    vector<long long> dp(max(n, 2));          // bottom-up tabulation
    dp[0] = 0; dp[1] = 1;
    for (int i = 2; i < n; i++) dp[i] = dp[i-1] + dp[i-2];
    for (int i = 0; i < n; i++) cout << dp[i] << " \n"[i==n-1];
    memo.assign(n+1, -1); if (n) cout << "F(" << n-1 << ")=" << fibMemo(n-1) << "\n";
}

