// cur = best sum of subarray ending here = max(x, cur + x)
long long kadane(const vector<long long>& a){
    long long cur = a[0], best = a[0];
    for (size_t i = 1; i < a.size(); i++) { cur = max(a[i], cur + a[i]); best = max(best, cur); }
    return best;   // works for all-negative arrays too
}
