#include <bits/stdc++.h>
using namespace std;
// Most common variation: houses in a circle (first and last adjacent) = House Robber II
long long robLine(const vector<long long>& a, int l, int r){
    long long p2 = 0, p1 = 0;
    for (int i = l; i <= r; i++) { long long c = max(p1, p2 + a[i]); p2 = p1; p1 = c; }
    return p1;
}
int main(){
    int n; cin >> n; vector<long long> a(n); for (auto &x : a) cin >> x;
    if (n == 1) { cout << a[0] << "\n"; return 0; }
    cout << max(robLine(a, 0, n-2), robLine(a, 1, n-1)) << "\n";  // exclude last, or exclude first
}

