// Assumed ops: N -> N-1, N -> N/2 (if even), N -> N/3 (if divisible by 3)
int main(){
    int n; cin >> n;
    vector<int> dp(n+1, 0);                 // dp[i] = min moves from i to 1
    for (int i = 2; i <= n; i++) {
        dp[i] = dp[i-1] + 1;
        if (i % 2 == 0) dp[i] = min(dp[i], dp[i/2] + 1);
        if (i % 3 == 0) dp[i] = min(dp[i], dp[i/3] + 1);
    }
    cout << dp[n] << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    vector<long long> a(n*n*n), dp(n*n*n);
    for (auto &x : a) cin >> x;
    auto id = [&](int x, int y, int z){ return (x*n + y)*n + z; };
    for (int x = 0; x < n; x++) for (int y = 0; y < n; y++) for (int z = 0; z < n; z++) {
        long long best = LLONG_MIN;
        if (x) best = max(best, dp[id(x-1,y,z)]);
        if (y) best = max(best, dp[id(x,y-1,z)]);
        if (z) best = max(best, dp[id(x,y,z-1)]);
        dp[id(x,y,z)] = a[id(x,y,z)] + (best == LLONG_MIN ? 0 : best);
    }
    cout << dp[id(n-1,n-1,n-1)] << "\n";
}

