// bottom-up: dp[j] = t[i][j] + min(dp[j], dp[j+1])
int main(){
    int n; cin >> n; vector<vector<long long>> t(n);
    for (int i = 0; i < n; i++) { t[i].resize(i+1); for (auto &x : t[i]) cin >> x; }
    vector<long long> dp = t[n-1];
    for (int i = n-2; i >= 0; i--)
        for (int j = 0; j <= i; j++) dp[j] = t[i][j] + min(dp[j], dp[j+1]);
    cout << dp[0] << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// process columns right-to-left: dp[r][c] = g[r][c] + max(dp[r-1][c+1], dp[r][c+1], dp[r+1][c+1])
int main(){
    int n, m; cin >> n >> m; vector<vector<long long>> g(n, vector<long long>(m));
    for (auto &row : g) for (auto &x : row) cin >> x;
    vector<vector<long long>> dp = g;
    for (int c = m-2; c >= 0; c--) for (int r = 0; r < n; r++) {
        long long best = dp[r][c+1];
        if (r > 0) best = max(best, dp[r-1][c+1]);
        if (r+1 < n) best = max(best, dp[r+1][c+1]);
        dp[r][c] = g[r][c] + best;
    }
    long long ans = 0; for (int r = 0; r < n; r++) ans = max(ans, dp[r][0]);
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// dp[s] = min coins for sum s; unbounded -> iterate sums ascending
int minCoins(const vector<int>& coins, int V){
    const int INF = INT_MAX / 2; vector<int> dp(V+1, INF); dp[0] = 0;
    for (int s = 1; s <= V; s++)
        for (int c : coins) if (c <= s && dp[s-c] + 1 < dp[s]) dp[s] = dp[s-c] + 1;
    return dp[V] >= INF ? -1 : dp[V];
}
int main(){ int n, V; cin >> n >> V; vector<int> c(n); for (auto &x : c) cin >> x; cout << minCoins(c, V) << "\n"; }

