// dp[i][j] = LCS of s[0..i), t[0..j)
int lcs(const string& s, const string& t){
    int n = s.size(), m = t.size(); vector<vector<int>> dp(n+1, vector<int>(m+1, 0));
    for (int i = 1; i <= n; i++) for (int j = 1; j <= m; j++)
        dp[i][j] = s[i-1] == t[j-1] ? dp[i-1][j-1] + 1 : max(dp[i-1][j], dp[i][j-1]);
    return dp[n][m];
}
int main(){ string s, t; cin >> s >> t; cout << lcs(s, t) << "\n"; }

#include <bits/stdc++.h>
using namespace std;
// answer = n + m - 2*LCS (rolling 1D LCS)
int main(){
    string s, t; cin >> s >> t; int n = s.size(), m = t.size();
    vector<int> prev(m+1, 0), cur(m+1, 0);
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++)
            cur[j] = s[i-1] == t[j-1] ? prev[j-1] + 1 : max(prev[j], cur[j-1]);
        swap(prev, cur);
    }
    cout << n + m - 2 * prev[m] << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// dp[s] = longest alternating run ending at i whose last element has sign s (0 neg, 1 pos)
int main(){
    int n; cin >> n; vector<long long> A(n), B(n);
    for (auto &x : A) cin >> x; for (auto &x : B) cin >> x;
    int dp[2] = {0, 0}, best = 0;           // 0 = impossible
    for (int i = 0; i < n; i++) {
        int nd[2] = {0, 0};
        for (long long v : {A[i], B[i]}) {
            int s = v > 0;
            nd[s] = max(nd[s], dp[!s] + 1);  // extend opposite-sign run, or start fresh (dp=0)
        }
        dp[0] = nd[0]; dp[1] = nd[1];
        best = max({best, dp[0], dp[1]});
    }
    cout << best << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// f[i]: at step i, next jump free; g[i]: at step i right after a 2/3-jump (next must be 1)
int main(){
    int N; long long A, B, C; cin >> N >> A >> B >> C;
    const long long INF = LLONG_MAX / 4;
    vector<long long> f(N+1, INF), g(N+1, INF); f[0] = 0;
    for (int i = 1; i <= N; i++) {
        f[i] = min(f[i-1], g[i-1]) + A;              // 1-step allowed from either state
        if (i >= 2 && f[i-2] < INF) g[i] = min(g[i], f[i-2] + B);
        if (i >= 3 && f[i-3] < INF) g[i] = min(g[i], f[i-3] + C);
    }
    cout << min(f[N], g[N]) << "\n";
}

