#include <bits/stdc++.h>
using namespace std;
// 0/1 counting knapsack; iterate sums downward so each element used once
long long countSubsets(const vector<int>& a, int X){
    vector<long long> dp(X+1, 0); dp[0] = 1;            // empty subset
    for (int v : a) for (int s = X; s >= v; s--) dp[s] += dp[s-v];   // add % MOD if required
    return dp[X];                                        // zeros handled: each doubles count
}
int main(){ int n, X; cin >> n >> X; vector<int> a(n); for (auto &x : a) cin >> x; cout << countSubsets(a, X) << "\n"; }

#include <bits/stdc++.h>
using namespace std;
// expand around each of the 2n-1 centres (same O(n^2) as the DP table, O(1) space)
string longestPal(const string& s){
    int n = s.size(), bestL = 0, bestLen = n ? 1 : 0;
    for (int c = 0; c < n; c++)
        for (int odd = 0; odd < 2; odd++) {
            int l = c, r = c + 1 - odd;              // odd=1 -> centre c, odd=0 -> centre between c,c+1
            while (l >= 0 && r < n && s[l] == s[r]) { l--; r++; }
            if (r - l - 1 > bestLen) { bestLen = r - l - 1; bestL = l + 1; }
        }
    return s.substr(bestL, bestLen);
}
