    vector<int> prev(n+1, NEG), cur(n+1); prev[0] = 0;
    for (int j = 1; j <= k; j++) {
        fill(cur.begin(), cur.end(), NEG);
        for (int i = j; i <= n; i++)
            for (int p = j-1; p < i; p++)
                if (prev[p] > NEG) cur[i] = max(cur[i], prev[p] + mode[p][i-1]);
