const long long MOD = 1e9+7;
// count strings starting with '0', ending with '1', no run of K ones; answer = 2x (reversal symmetry)
// z[i] = #valid length-i strings (starting with 0) ending in '0'; t[i] = all valid length-i strings
// t[i] = z[i] + z[i-1] + ... + z[i-K+1]  (ending with r ones after the last 0), z[i] = t[i-1]
int main(){
    long long N, K; cin >> N >> K;
    if (N < 2) { cout << 0 << "\n"; return 0; }
    vector<long long> z(N+1, 0), t(N+1, 0), pz(N+1, 0);   // pz = prefix sums of z
    z[1] = 1; t[1] = 1; pz[1] = 1;
    for (long long i = 2; i <= N; i++) {
        z[i] = t[i-1];
        pz[i] = (pz[i-1] + z[i]) % MOD;
        long long lo = max(0LL, i - K);                    // sum z[lo+1..i]
        t[i] = ((pz[i] - pz[lo]) % MOD + MOD) % MOD;
    }
    long long endOne = ((t[N] - z[N]) % MOD + MOD) % MOD;
    cout << 2 * endOne % MOD << "\n";
}

