// dp[i][k] = min fatigue standing on stone i, last jump length k (k <= i+1 since jumps grow by <=1)
int main(){
    int n; cin >> n; vector<long long> p(n); for (auto &x : p) cin >> x;
    unordered_map<long long,int> idx; for (int i = 0; i < n; i++) idx[p[i]] = i;
    const int INF = INT_MAX / 2;
    vector<vector<int>> dp(n, vector<int>(n+2, INF));
    if (n == 1) { cout << 0 << "\n"; return 0; }
    if (!idx.count(p[0] + 1)) { cout << -1 << "\n"; return 0; }
    dp[idx[p[0]+1]][1] = 0;                        // first jump is 1, no fatigue (assumed)
    for (int i = 1; i < n; i++) for (int k = 1; k <= i + 1; k++) {
        if (dp[i][k] >= INF) continue;
        for (int nk = k - 1; nk <= k + 1; nk++) {
            if (nk <= 0) continue;
            auto it = idx.find(p[i] + nk); if (it == idx.end()) continue;
            int j = it->second, c = dp[i][k] + (nk > k);
            if (nk <= n && c < dp[j][nk]) dp[j][nk] = c;
        }
    }
    int ans = INF; for (int k = 0; k <= n + 1; k++) ans = min(ans, dp[n-1][k]);
    cout << (ans >= INF ? -1 : ans) << "\n";
}

