// strictly increasing then strictly decreasing, any integers allowed for changed cells.
// kept i<j on rising side need a[j]-a[i] >= j-i  <=> (a-i) non-decreasing ; falling side: (a+i) non-increasing
int main(){
    int n; cin >> n; vector<long long> a(n); for (auto &x : a) cin >> x;
    vector<int> pre(n+1, 0), suf(n+2, 0);              // pre[p] = best keep in a[0..p-1]
    vector<long long> tails;
    for (int i = 0; i < n; i++) {
        long long b = a[i] - i;                         // longest non-decreasing subsequence
        auto it = upper_bound(tails.begin(), tails.end(), b);
        if (it == tails.end()) tails.push_back(b); else *it = b;
        pre[i+1] = tails.size();
    }
    tails.clear();
    for (int i = n - 1; i >= 0; i--) {                  // from the right, a+i must be non-decreasing
        long long b = a[i] + i;
        auto it = upper_bound(tails.begin(), tails.end(), b);
        if (it == tails.end()) tails.push_back(b); else *it = b;
        suf[i] = tails.size();                          // best keep in a[i..n-1]
    }
    int best = 0;
    for (int p = 0; p <= n; p++) best = max(best, pre[p] + suf[p]);
    cout << n - best << "\n";
}

