            if (j) v = min(v, dp[i][j-1][md] + 15);                     // insert
            if (i && j) v = min(v, dp[i-1][j-1][md] + rep(A[i-1], B[j-1], md));
        }
        dp[i][j][0] = min(dp[i][j][0], dp[i][j][1] + K);               // switch at this point
        dp[i][j][1] = min(dp[i][j][1], dp[i][j][0] + K);
    }
    cout << min(dp[n][m][0], dp[n][m][1]) << "\n";
}

