// dp[k][i] = min over j of dp[k-1][j] + cost(j..i-1); cost built incrementally while j moves left
int main(){
    int n, K; cin >> n >> K; vector<long long> a(n); for (auto &x : a) cin >> x;
    const long long INF = LLONG_MAX / 4;
    vector<long long> prev(n+1, INF), cur(n+1); prev[0] = 0;
    for (int k = 1; k <= K; k++) {
        fill(cur.begin(), cur.end(), INF);
        for (int i = 1; i <= n; i++) {                    // segment ends at i-1
            long long mx = LLONG_MIN, mn = LLONG_MAX;
            for (int j = i - 1; j >= k - 1; j--) {        // segment a[j..i-1]
                mx = max(mx, a[j]); mn = min(mn, a[j]);
                if (prev[j] < INF) cur[i] = min(cur[i], prev[j] + (mx - mn) + llabs(a[j] - a[i-1]));
