using namespace std;
// f0 = longest path from cell without using the jump, f1 = with the jump still allowed
// process cells by decreasing value so every strictly greater target is already final
int main(){
    int n, m; cin >> n >> m; vector<vector<long long>> g(n, vector<long long>(m));
    for (auto &r : g) for (auto &x : r) cin >> x;
    vector<array<int,2>> cells;
    for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) cells.push_back({i, j});
    sort(cells.begin(), cells.end(), [&](auto &a, auto &b){ return g[a[0]][a[1]] > g[b[0]][b[1]]; });
    vector<vector<int>> f0(n, vector<int>(m, 1)), f1(n, vector<int>(m, 1));
    int dx[4] = {1,-1,0,0}, dy[4] = {0,0,1,-1}, ans = 0;
    for (auto [x, y] : cells) {
        for (int d = 0; d < 4; d++) {
            int a = x + dx[d], b = y + dy[d];
            if (a >= 0 && a < n && b >= 0 && b < m && g[a][b] > g[x][y]) {
                f0[x][y] = max(f0[x][y], 1 + f0[a][b]);
                f1[x][y] = max(f1[x][y], 1 + f1[a][b]);
            }
            a = x + 2*dx[d]; b = y + 2*dy[d];                       // the one allowed jump
            if (a >= 0 && a < n && b >= 0 && b < m && g[a][b] > g[x][y])
                f1[x][y] = max(f1[x][y], 1 + f0[a][b]);
        }
        ans = max(ans, f1[x][y]);
    }
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// dp[i] = 1 + max dp[j] (j<i) with a[i]-D <= a[j] < a[i]; segment tree (range max) on compressed values
int main(){
    int n; long long D; cin >> n >> D; vector<long long> a(n); for (auto &x : a) cin >> x;
    vector<long long> v = a; sort(v.begin(), v.end()); v.erase(unique(v.begin(), v.end()), v.end());
    int m = v.size(); vector<int> t(2*m, 0);                 // iterative segment tree
    auto upd = [&](int p, int val){ p += m; t[p] = max(t[p], val);
        for (p >>= 1; p; p >>= 1) t[p] = max(t[2*p], t[2*p+1]); };
    auto qry = [&](int l, int r){ int res = 0; for (l += m, r += m; l < r; l >>= 1, r >>= 1) {
        if (l & 1) res = max(res, t[l++]); if (r & 1) res = max(res, t[--r]); } return res; };   // [l,r)
    int ans = 0;
    for (int i = 0; i < n; i++) {
        int lo = lower_bound(v.begin(), v.end(), a[i] - D) - v.begin();
        int hi = lower_bound(v.begin(), v.end(), a[i]) - v.begin();   // strictly smaller values
        int cur = qry(lo, hi) + 1;
        upd(hi, cur); ans = max(ans, cur);
    }
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// CF 833B: dp_k[i] = max_j dp_{k-1}[j] + distinct(j+1..i); seg tree over j with range add:
// a[i] adds +1 to every j in [last[a[i]], i-1]
int n, K; vector<int> mx, lz;
void add(int o, int l, int r, int ql, int qr, int v){
    if (qr < l || r < ql) return;
    if (ql <= l && r <= qr) { mx[o] += v; lz[o] += v; return; }
    int m = (l + r) / 2; add(2*o, l, m, ql, qr, v); add(2*o+1, m+1, r, ql, qr, v);
    mx[o] = max(mx[2*o], mx[2*o+1]) + lz[o];
}
int query(int o, int l, int r, int ql, int qr){
    if (qr < l || r < ql) return INT_MIN / 2;
    if (ql <= l && r <= qr) return mx[o];
    int m = (l + r) / 2; return max(query(2*o, l, m, ql, qr), query(2*o+1, m+1, r, ql, qr)) + lz[o];
}
int main(){
    cin >> n >> K; vector<int> a(n+1); for (int i = 1; i <= n; i++) cin >> a[i];
    const int NEG = INT_MIN / 4; vector<int> prev(n+1, NEG), cur(n+1); prev[0] = 0;
    for (int k = 1; k <= K; k++) {
        mx.assign(4*(n+1), 0); lz.assign(4*(n+1), 0);
        for (int j = 0; j <= n; j++) add(1, 0, n, j, j, prev[j]);       // leaf j holds dp_{k-1}[j]
        map<int,int> last; fill(cur.begin(), cur.end(), NEG);
        for (int i = 1; i <= n; i++) {
            int lp = last.count(a[i]) ? last[a[i]] : 0;  last[a[i]] = i;
            add(1, 0, n, lp, i-1, 1);                                 // segments starting after lp gain a[i]
            if (i >= k) cur[i] = query(1, 0, n, k-1, i-1);
        }
        prev = cur;
    }
    cout << prev[n] << "\n";
}

