// dp[i] = best for prefix of length i (non-decreasing in i). Segment [j, i-1] has mex >= m
// iff j <= t_m = min(last[0..m-1]). So dp[i] = max(dp[i-1], max_m m + dp[t_m]).
int main(){
    int n; cin >> n; vector<int> a(n); for (auto &x : a) cin >> x;
    const int V = 1002; vector<int> last(V, -1); vector<long long> dp(n+1, 0);
    for (int i = 1; i <= n; i++) {
        if (a[i-1] < V) last[a[i-1]] = i - 1;
        dp[i] = dp[i-1];                                   // mex 0 segment / extend previous
        int t = INT_MAX;
        for (int m = 1; m < V; m++) {
            if (last[m-1] < 0) break;                      // value m-1 never seen -> mex can't reach m
            t = min(t, last[m-1]);                         // latest start keeping 0..m-1 inside
            dp[i] = max(dp[i], dp[t] + m);
        }
    }
    cout << dp[n] << "\n";
}

