using namespace std;
// state of current cell: 0 = number, next must NOT be a mine; 1 = number, next MUST be a mine; 2 = mine; 3 = start
const long long MOD = 1e9+7;
int main(){
    string s; cin >> s; int n = s.size();
    long long dp[4] = {0, 0, 0, 1};                    // before position 0: free 'start' state
    for (int i = 0; i < n; i++) {
        long long nd[4] = {0, 0, 0, 0}; char c = s[i];
        // place a mine: previous must not be state 0
        if (c == '*' || c == '?') nd[2] = (dp[1] + dp[2] + dp[3]) % MOD;
        // place digit d: previous can't be state 1; left mine count = (prev==2)
        for (int d = 0; d <= 2; d++) {
            if (c != '?' && c != '0' + d) continue;
            for (int p : {0, 2, 3}) {
                int need = d - (p == 2);
                if (need == 0) nd[0] = (nd[0] + dp[p]) % MOD;
                else if (need == 1) nd[1] = (nd[1] + dp[p]) % MOD;
            }
        }
        dp[0] = nd[0]; dp[1] = nd[1]; dp[2] = nd[2]; dp[3] = 0;
    }
    cout << (dp[0] + dp[2]) % MOD << "\n";        // last cell can't demand a mine to its right
}

