using namespace std;
// Samples match: Kevin scores A of the smaller-B element, Paul scores B of the larger-B element.
// Score = sum_K (A+B) - sum_all B. Feasible Kevin sets: in decreasing-B order, every prefix of
// length t has at most floor(t/2) Kevin elements -> greedy with a min-heap.
int main(){
    int n; cin >> n; vector<long long> A(n), B(n);
    for (auto &x : A) cin >> x; for (auto &x : B) cin >> x;
    vector<int> id(n); iota(id.begin(), id.end(), 0);
    sort(id.begin(), id.end(), [&](int x, int y){ return B[x] > B[y]; });
    priority_queue<long long, vector<long long>, greater<long long>> pq; long long sumB = 0, sumK = 0;
    for (int t = 1; t <= n; t++) {
        int i = id[t-1]; sumB += B[i];
        pq.push(A[i] + B[i]); sumK += A[i] + B[i];
        if ((int)pq.size() > t / 2) { sumK -= pq.top(); pq.pop(); }
    }
    cout << sumK - sumB << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// digit DP: (pos, remainder mod K, even-odd balance, tight, started)
string N; int K; vector<vector<vector<long long>>> memo;
long long go(int pos, int rem, int bal, bool tight, bool started){
    if (pos == (int)N.size()) return started && rem == 0 && bal == 0;
    if (!tight && started && memo[pos][rem][bal + 10] != -1) return memo[pos][rem][bal + 10];
    long long res = 0; int lim = tight ? N[pos] - '0' : 9;
    for (int d = 0; d <= lim; d++) {
        bool ns = started || d != 0;
        int nb = ns ? bal + (d % 2 == 0 ? 1 : -1) : 0;     // leading zeros don't count
        res += go(pos + 1, (rem * 10 + d) % K, nb, tight && d == lim, ns);
    }
    if (!tight && started) memo[pos][rem][bal + 10] = res;
    return res;
}
int main(){
    long long n; cin >> n >> K; N = to_string(n);
    memo.assign(N.size(), vector<vector<long long>>(K, vector<long long>(21, -1)));
    cout << go(0, 0, 0, true, false) << "\n";
}

