// revenue_i computed directly (O(n) each; use offline BIT if n*m is too big),
// then weighted interval scheduling over positions: best[p] = max(best[p-1], best[L-1] + w for R==p)
int main(){
    int n, m; cin >> n >> m; vector<long long> v(n+1);
    for (int i = 1; i <= n; i++) cin >> v[i];
    vector<vector<pair<int,long long>>> endAt(n+1);       // (L, revenue) grouped by R
    for (int k = 0; k < m; k++) {
        int L, R; long long X, Y; cin >> L >> R >> X >> Y; long long w = 0;
        for (int i = L; i <= R; i++) if (v[i] >= X && v[i] <= Y) w += v[i];
        endAt[R].push_back({L, w});
    }
    vector<long long> best(n+1, 0);
    for (int p = 1; p <= n; p++) {
        best[p] = best[p-1];
        for (auto [L, w] : endAt[p]) best[p] = max(best[p], best[L-1] + w);
    }
    cout << best[n] << "\n";
}

