        for (int r1 = max(0, s-n+1); r1 <= min(n-1, s); r1++) for (int r2 = max(0, s-n+1); r2 <= min(n-1, s); r2++) {
            long long best = NEG;
            for (int a = 0; a < 2; a++) for (int b = 0; b < 2; b++) {   // previous rows r1-a, r2-b
                int p1 = r1 - a, p2 = r2 - b;
                if (p1 >= 0 && p2 >= 0 && s-1-p1 >= 0 && s-1-p2 >= 0 && s-1-p1 < n && s-1-p2 < n) best = max(best, dp[p1][p2]);
            }
            if (best == NEG) continue;
            long long gain = g[r1][s-r1] + (r1 != r2 ? g[r2][s-r2] : 0);
            nd[r1][r2] = best + gain;
        }
        dp = nd;
    }
    cout << dp[n-1][n-1] << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Cherry Pickup (LC 741): round trip == two walkers going down/right together; -1 cells blocked
int main(){
    int n; cin >> n; vector<vector<int>> g(n, vector<int>(n));
    for (auto &r : g) for (auto &x : r) cin >> x;
    const int NEG = INT_MIN / 4;
    vector<vector<int>> dp(n, vector<int>(n, NEG)), nd;
    if (g[0][0] == -1) { cout << 0 << "\n"; return 0; }
    dp[0][0] = g[0][0];
    for (int s = 1; s <= 2*n - 2; s++) {
        nd.assign(n, vector<int>(n, NEG));
        for (int r1 = max(0, s-n+1); r1 <= min(n-1, s); r1++) for (int r2 = max(0, s-n+1); r2 <= min(n-1, s); r2++) {
            int c1 = s - r1, c2 = s - r2;
            if (g[r1][c1] == -1 || g[r2][c2] == -1) continue;
            int best = NEG;
            for (int a = 0; a < 2; a++) for (int b = 0; b < 2; b++) {
                int p1 = r1 - a, p2 = r2 - b;
                if (p1 >= 0 && p2 >= 0 && s-1-p1 >= 0 && s-1-p2 >= 0) best = max(best, dp[p1][p2]);
            }
            if (best == NEG) continue;
            nd[r1][r2] = best + g[r1][c1] + (r1 != r2 ? g[r2][c2] : 0);
        }
        dp = nd;
    }
    cout << max(0, dp[n-1][n-1]) << "\n";             // unreachable -> 0
}

#include <bits/stdc++.h>
using namespace std;
// state = last two values (x, y); next z needs gcd(y,z)==1 and gcd(x,z)>1
const long long MOD = 1e9+7;
int main(){
    int N, K; cin >> N >> K;
    if (N == 1) { cout << K << "\n"; return 0; }
    vector<vector<long long>> dp(K+1, vector<long long>(K+1, 0));
    for (int x = 1; x <= K; x++) for (int y = 1; y <= K; y++) if (gcd(x, y) == 1) dp[x][y] = 1;
    for (int len = 3; len <= N; len++) {
        vector<vector<long long>> nd(K+1, vector<long long>(K+1, 0));
        for (int x = 1; x <= K; x++) for (int y = 1; y <= K; y++) if (dp[x][y])
            for (int z = 1; z <= K; z++)
                if (gcd(y, z) == 1 && gcd(x, z) > 1) nd[y][z] = (nd[y][z] + dp[x][y]) % MOD;
        dp = nd;
    }
    long long ans = 0;
    for (int x = 1; x <= K; x++) for (int y = 1; y <= K; y++) ans = (ans + dp[x][y]) % MOD;
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// f0: no teleport left, f1: teleport still available. Teleport target = any strictly greater cell,
// so f1 uses the best f0 among all strictly greater values (process equal values as one group).
int main(){
    int n, m; cin >> n >> m; vector<vector<long long>> g(n, vector<long long>(m));
    for (auto &r : g) for (auto &x : r) cin >> x;
    vector<array<int,2>> c;
    for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) c.push_back({i, j});
    sort(c.begin(), c.end(), [&](auto &a, auto &b){ return g[a[0]][a[1]] > g[b[0]][b[1]]; });
    vector<vector<int>> f0(n, vector<int>(m, 1)), f1(n, vector<int>(m, 1));
    int dx[4] = {1,-1,0,0}, dy[4] = {0,0,1,-1}, bestGreater = 0, ans = 0;
    for (size_t s = 0; s < c.size(); ) {
        size_t e = s; while (e < c.size() && g[c[e][0]][c[e][1]] == g[c[s][0]][c[s][1]]) e++;
        for (size_t k = s; k < e; k++) {
            auto [x, y] = c[k];
            f1[x][y] = 1 + bestGreater;                             // teleport now
            for (int d = 0; d < 4; d++) {
                int a = x + dx[d], b = y + dy[d];
                if (a < 0 || a >= n || b < 0 || b >= m || g[a][b] <= g[x][y]) continue;
                f0[x][y] = max(f0[x][y], 1 + f0[a][b]);
                f1[x][y] = max(f1[x][y], 1 + f1[a][b]);
            }
            ans = max(ans, f1[x][y]);
        }
        for (size_t k = s; k < e; k++) bestGreater = max(bestGreater, f0[c[k][0]][c[k][1]]);
        s = e;
    }
    cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// (x&y)*2 < (x|y)  <=>  (x&y) < (x^y)  <=>  x and y have different highest set bits (0 counts as class -1).
// With x<y this means msb strictly increases -> longest subsequence with strictly increasing msb class.
int main(){
    int n; cin >> n; vector<long long> a(n); for (auto &x : a) cin >> x;
    vector<int> best(65, 0);                          // best[c] = longest valid subsequence ending in class c
    for (long long x : a) {
        int c = x == 0 ? 0 : 64 - __builtin_clzll(x);  // class 0 for zero, msb+1 otherwise
        int prev = 0; for (int d = 0; d < c; d++) prev = max(prev, best[d]);
        best[c] = max(best[c], prev + 1);
    }
    cout << *max_element(best.begin(), best.end()) << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// dp[b][i] = max strength using exactly b beacons inside prefix s[0..i); pal[j][i] precomputed
int main(){
    int n, B; string s; cin >> n >> B >> s;
    vector<vector<int>> startsEndingAt(n+1);           // for end i (exclusive), all j with s[j..i) palindrome
    for (int c = 0; c < n; c++) for (int e = 0; e < 2; e++) {   // e=0 odd centre (c,c), e=1 even (c,c+1)
        int l = c, r = c + e;
        while (l >= 0 && r < n && s[l] == s[r]) { startsEndingAt[r+1].push_back(l); l--; r++; }
    }
    const int NEG = INT_MIN / 4;
    vector<vector<int>> dp(B+1, vector<int>(n+1, NEG));
    for (int i = 0; i <= n; i++) dp[0][i] = 0;
    for (int b = 1; b <= B; b++)
        for (int i = 1; i <= n; i++) {
            dp[b][i] = dp[b][i-1];                     // s[i-1] not covered
            for (int j : startsEndingAt[i])
                if (dp[b-1][j] > NEG) dp[b][i] = max(dp[b][i], dp[b-1][j] + (i - j));
        }
    cout << (dp[B][n] > NEG ? dp[B][n] : -1) << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// dp[mask][r] = #ways to arrange the digits in mask (as a prefix) with value % k == r
const long long MOD = 1e9+7;
int main(){
    string x; int y, k; cin >> x >> y >> k;            // x written in base y, distinct digits
    vector<int> d; for (char c : x) d.push_back(isdigit(c) ? c - '0' : toupper(c) - 'A' + 10);
    int n = d.size();
    vector<vector<long long>> dp(1 << n, vector<long long>(k, 0)); dp[0][0] = 1;
    for (int mask = 0; mask < (1 << n); mask++) for (int r = 0; r < k; r++) {
        if (!dp[mask][r]) continue;
        for (int i = 0; i < n; i++) if (!(mask >> i & 1)) {
            if (mask == 0 && d[i] == 0 && n > 1) continue;   // no leading zero (assumption)
            int nr = (r * y + d[i]) % k;
            dp[mask | 1 << i][nr] = (dp[mask | 1 << i][nr] + dp[mask][r]) % MOD;
        }
    }
    cout << dp[(1 << n) - 1][0] << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// odd[i] / even[i] = best sum of a valid sequence ending at i with i at an odd / even position.
// odd[i] = A+B + max(0, max even[j]), even[i] = A-B + max odd[j], over j<i with A[j] <= A[i]
// -> two Fenwick trees (prefix max) over compressed A values.
const long long NEG = LLONG_MIN / 4;
struct BIT { int n; vector<long long> t; BIT(int n): n(n), t(n+1, NEG) {}
    void upd(int i, long long v){ for (; i <= n; i += i & -i) t[i] = max(t[i], v); }
    long long qry(int i){ long long r = NEG; for (; i > 0; i -= i & -i) r = max(r, t[i]); return r; } };
int main(){
    int n; cin >> n; vector<long long> A(n), B(n); for (auto &x : A) cin >> x; for (auto &x : B) cin >> x;
    vector<long long> v = A; sort(v.begin(), v.end()); v.erase(unique(v.begin(), v.end()), v.end());
    BIT od(v.size()), ev(v.size()); long long ans = NEG;
    for (int i = 0; i < n; i++) {
        int p = lower_bound(v.begin(), v.end(), A[i]) - v.begin() + 1;
        long long be = ev.qry(p), bo = od.qry(p);
        long long o = A[i] + B[i] + max(0LL, be);             // start new or extend an even-ending seq
        long long e = bo > NEG ? A[i] - B[i] + bo : NEG;
        od.upd(p, o); if (e > NEG) ev.upd(p, e);
        ans = max({ans, o, e});
    }
    const long long MOD = 1e9+7;
    cout << ((ans % MOD) + MOD) % MOD << "\n";
}

#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1e9+7;
long long pw(long long b, long long e){ long long r = 1; b %= MOD; while (e) { if (e & 1) r = r*b % MOD; b = b*b % MOD; e >>= 1; } return r; }
// c[v] = #rows with max exactly v = v^M - (v-1)^M; dp over rows with window sums of width 2X+1
int main(){
    long long N, M, K, X; cin >> N >> M >> K >> X;
    vector<long long> c(K+1), dp(K+1), pre(K+1);
    for (int v = 1; v <= K; v++) c[v] = (pw(v, M) - pw(v-1, M) + MOD) % MOD;
    for (int v = 1; v <= K; v++) dp[v] = c[v];
    for (long long r = 2; r <= N; r++) {
        pre[0] = 0; for (int v = 1; v <= K; v++) pre[v] = (pre[v-1] + dp[v]) % MOD;
        for (int v = 1; v <= K; v++) {
            long long lo = max(1LL, v - X), hi = min(K, v + X);
            dp[v] = c[v] * ((pre[hi] - pre[lo-1] + MOD) % MOD) % MOD;
        }
    }
    long long ans = 0; for (int v = 1; v <= K; v++) ans = (ans + dp[v]) % MOD;
    cout << ans << "\n";
}
